import React from 'react';
import { Input, Button, Field } from '@alifd/next';

class Demo extends React.Component {
    field = new Field(this, {
        values: {
            name: 'initial value'
        }
    });

    onClick = () => {
        this.field.setValue('name', 'new value');
        console.log(this.field.getValue('name')); // Should log 'new value', but logs 'initial value'
    }

    render() {
        const init = this.field.init;

        return (
            <div>
                <Input {...init('name')} />
                <Button onClick={this.onClick}>Change Value</Button>
            </div>
        );
    }
}

ReactDOM.render(<Demo />, mountNode);
